def add(id,title,priority,category,journeys,steps,actual,measured,cause,source,evidence,solution,acceptance,status='confirmed',complexity='M',risk='A régi mentések, megosztott adatok és RPC-szerződések kompatibilitását meg kell őrizni.'):
 findings.append(dict(id=id,title=title,priority=priority,severity='high' if priority=='P1' else 'medium' if priority=='P2' else 'low',category=category,affectedJourneys=journeys,confidence='high' if status=='confirmed' else 'low',validationStatus=status,reproductionSteps=steps,expectedBehavior=acceptance[0],actualBehavior=actual,measuredImpact=measured,rootCause=cause,sourceFiles=source,evidence=evidence,recommendedRemediation=solution,acceptanceCriteria=acceptance,estimatedComplexity=complexity,risks=risk,regressionTests=steps))
add('PERF-001','Ismételt kategóriakeresés blokkolja a bevásárlólista renderelését','P1','frontend',['J2','J4','J7'],['50, 250, majd 667 szintetikus katalógustétel kerüljön a készletbe és a listára.','Áttekintésből kattintás a Lista fülre.','A long-task adatok és a shopping-667.cpuprofile ellenőrzése.'],'667 tételnél 4225 ms főszál-feladat és 4327 ms navigáció; külön profilozott ismétlés: 4186 ms. 2000 tételnél a kattintás 30 s után időtúllépett.',{'items667':{'longTaskMs':4225,'navigationMs':4327},'items250NavigationMs':350,'items2000TimeoutMs':30000},'A shoppingGroupHeader minden csoporthoz újraszűri a teljes listát. A productCategory minden összehasonlításnál új tömböt épít, kisbetűsít és lineárisan keres. A CPU-profil forró pontja app.js:15.',['app.js:15','app.js:175','app.js:198'],[full['ref']+'#scaling',sup['dir']+'/traces/shopping-667.cpuprofile',full['dir']+'/traces/long-session.zip'],'Normalizált név → kategória index; csoportosítás és darabszámok egy menetben. Szükség esetén ezt kövesse DOM-ablakozás.',['250 tételnél a meleg Lista-váltás p95 ≤ 200 ms.','667 tételnél nincs 200 ms feletti alkalmazáskód-feladat.','2000 tételnél sem veszhet el a navigáció válaszkészsége.','Magyar/angol nevek és egyéni tételek helyes kategóriában maradnak.'])
add('PERF-002','Pontos recept-alapanyagokhoz is teljes fuzzy keresés fut','P1','frontend',['J2','J5'],['31 seed-recept, 50 tételes készlet/lista.','Receptek / Neked megnyitása.','recipes-50.cpuprofile megnyitása DevToolsban.'],'Már 50 tételnél 527 ms-os főszál-feladat; a profilozott megnyitás 643 ms-os intervalluma főként QuickEntry keresés.',{'longTaskMs':527,'profileDurationMs':643},'recipe-library.cards → discoverySections → recipeChoice → resolve → QuickEntry.match. A ranked minden katalógusnévre Levenshtein-távolságot számol akkor is, amikor a név pontosan egyezik.',['quick-entry.js:2','quick-entry.js:4','quick-entry.js:5','quick-entry.js:6','recipe-library.js:26','kitchen-model.js:58'],[full['ref']+'#scaling',sup['dir']+'/traces/recipes-50.cpuprofile',sup['dir']+'/traces/recipes-250.cpuprofile'],'Pontos és alias-egyezések indexelése; fuzzy keresés csak elírásnál. A recept-alapanyag feloldásokat a katalógusverzióhoz kötötten cache-elni.',['A 24 kártyás meleg ajánló renderelése p95 ≤ 200 ms.','Pontos neveknél nincs teljes katalógusos távolságszámítás.','Az elírt és ékezet nélküli gyors bevitel megmarad.'])
add('PERF-003','Az AI előkészítése látható folyamatjelzés nélkül vár','P1','ai',['J6'],['Új chat egy szintetikus bejelentkezett fiókkal.','Minden RPC-válasz 600 ms mesterséges késleltetést kap.','Küldés után 800 ms-nál képernyő és vezérlőállapot rögzítése.'],'800 ms-nál az üzenet még a mezőben áll, a Küldés gomb aktív, nincs thinking és Stop. Az azonnali helyi AI-válasz is csak 3338 ms körül látható.',{'rpcDelayMs':600,'noFeedbackAtMs':800,'totalMs':F['aiPreflight']['totalMs'],'rpcBeforeProviderSpanMs':2743},'send előbb await-eli a beginTurn műveletet; a busy és renderChat később fut. A beginTurn flush/refresh, zárolás és történetolvasás láncot végez. Globális focusout további frissítést indíthat.',['companion-ui.js:199','companion-ui.js:201','companion-ui.js:206','persistence.js:44','persistence.js:102','persistence.js:104'],[full['ref']+'#aiPreflight',full['dir']+'/screenshots/22-ai-preflight-800ms.png',full['dir']+'/traces/journeys.zip'],'Az egész előkészítési szakasz kapjon azonnali, megszakítható sending állapotot. A zárolási/mentési garanciák mellett a fölösleges olvasások összevonása.',['Küldés után ≤ 100 ms-on belül látható állapotváltozás.','Előkészítés közben működő megszakítás.','Dupla küldés nem indít két modelligényt.','Másik eszköz turn-lockja továbbra is érvényes.'])
add('PERF-004','A közös készlet teljes hálózati lánca lezárja a párbeszédablakot','P1','reliability',['J3'],['Közös háztartásban Rizs-részletek megnyitása.','Minden REST-válasz késleltetése 450 ms-mal.','Van otthon választása, majd a bezáró- és műveleti gombok ellenőrzése.'],'Az összes gomb, a bezárás is tiltott; a művelet 2952 ms-ot vett igénybe.',{'perRequestDelayMs':450,'operationMs':F['sharedPantry']['durationMs']},'openPantryDetails minden gombot letilt és a cancel eseményt blokkolja, amíg updatePantryAvailability a saveVoiceState → household.push → fetchRows és PantryReview.confirm láncot végigvárja. Ez műveleti zárolás, nem általános JavaScript-fagyás.',['pantry-library.js:28','pantry-library.js:44','pantry-library.js:51','household.js:144','household.js:111'],[full['ref']+'#sharedPantry',full['ref']+'#sharedPantryPending',full['dir']+'/screenshots/25-shared-pantry-saving.png',full['dir']+'/traces/shared.zip'],'Bezárható párbeszédablak, helyi pending állapot és mentési nyugta külön kezelése. A mutációs válasz adhassa vissza a megerősített új állapotot, ahol ez biztonságos.',['450 ms-os hálózatnál a vezérlők azonnal visszajeleznek és az ablak bezárható.','Sikeres mentés csak szervernyugta után látszik.','Hibánál a felhasználói szándék és az újrapróbálás megmarad.'])
add('PERF-005','A web build 60 szinkron scriptet és kb. 1 MB nyers JS/CSS-t tölt','P2','startup',['J1'],['build:web a pillanatképen.','390 px-es hideg indítás 150 ms RTT és 200000 byte/s letöltés mellett.','Meleg cache és 400 ms RTT megismétlése.'],'703084 byte JS és 305846 byte CSS változatlanul kerül a buildbe. Lassú 4G laborprofil: hideg LCP medián 5768 ms, használhatósági próba 6206 ms.',{'scripts':60,'deferScripts':0,'jsBytes':703084,'cssBytes':305846,'coldSlow4gLcpMs':5768},'Nincs alkalmazásbundle, minifikálás vagy kódfelosztás a web buildben. A klasszikus globális scriptfüggőségek és a sok erőforrás több hálózati kört igényelnek.',['index.html:1','scripts/build-mobile.mjs:5','styles.css:1','workspace.css:1'],['resources.json',full['ref']+'#startup'],'Explicit buildfüggőségek; minifikált kezdeti csomag; ritka hang/kép funkciók késleltetett betöltése. Stagingen a tömörítés és cache ellenőrzése.',['LCP ≤ 2.5 s cél a kijelölt mobilprofilon.','Külön kezdeti JS/CSS transfer budget.','Az inicializációs sorrend és mind az öt nézet működése megmarad.'],risk='A mérés helyi HTTP/1.1 és tömörítés nélküli. A CDN HTTP/2/3, gzip/Brotli és cache eltérése miatt ez nem éles weboldal-latencia.')
add('PERF-006','Realtime mellett is sok teljes háttérolvasás történik','P2','realtime',['J2','J3','J4','J7'],['Két szintetikus közös háztartási kliens.','20 egyidejű Phoenix postgres_changes jel az egyik kliensnek.','16.5 s változtatás nélküli időszak megfigyelése.'],'A burst helyesen egy refresh-ciklussá áll össze, de az 8 REST-kérést indít. Két kliens 16.5 s alatt 42 kérést végzett. Kliensenként 2 socket maradt.',{'burstEvents':20,'burstRequests':len(F['realtimeBurst']['calls']),'idleTwoClientRequests':len(F['idlePolling']['calls']),'idleMs':16500,'sockets':2},'A household.refresh minden alkalommal teljes ellenőrzött fetchRows-t, majd pantry/kitchen/shopping frissítéseket indít. A 8 s-os poll egészséges Realtime mellett is marad; a perzisztencia 15 s-os és globális focusout-frissítése hozzáadódik.',['household.js:111','household.js:120','household.js:125','household.js:157','persistence.js:101','persistence.js:103'],[full['ref']+'#realtimeBurst',full['ref']+'#idlePolling'],'Adatkörönkénti invalidálás, megosztott aktív olvasások, egészséges Realtime mellett ritkább egyeztetés. A polling fallback megőrzése.',['Eseményviharban legfeljebb egy aktív egyeztetési ciklus.','Változatlan adatoknál nincs teljes mellékadatfrissítés.','Egészséges kapcsolatban cél ≤ 4 háttérkérés/perc/kliens; fallback külön kerettel.'])
add('PERF-007','A beszélgetésindex a teljes táblán értékeli a hozzáférést','P2','database',['J6','J7'],['50 látható beszélgetés mellett 100 → 1000 → 5000 teljes sor.','conversation_index(0) és belső SELECT: EXPLAIN ANALYZE.','Diagnosztikus owner_id-szűrés összevetése, a megosztási szemantika eltérésének jelölésével.'],'A PGlite minimumidő kb. 1.8 → 6.2 → 26.9 ms. Az 5000 sorból 4950-et a can_read_conversation szűrés dobott el, végig 50 látható sor mellett.',{'rows':5000,'visibleRows':50,'filteredOut':4950,'minimumMs':[1.8,6.2,26.9]},'A belső feltétel csak can_read_conversation(id), előzetes owner/shared jelöltszűrés nélkül. A meglévő owner-index ebben a tervben minden kulcsot végigolvas, a jogosultság soronként értékelődik.',['supabase/migrations/20261114_persistent_library.sql:153','supabase/migrations/20261114_persistent_library.sql:29'],[dbref+'#plans/conversation_inner_5000'],'Indexelt saját és megosztott jelöltek egyesítése, majd a szükséges hozzáférési ellenőrzés. Keyset lapozás mérlegelése. Az owner-only diagnosztika nem kész helyettesítő query.',['Idegen beszélgetések növelése ne okozzon lineáris listázási költséget.','Privát/megosztott olvasás, visszavonás, törlés és archiválás tesztjei átmennek.'],risk='A számok WASM-laborértékek. Éles slow query vagy lock contention nem lett mérve.')
add('PERF-008','Egy lassú kép más képek cache-olvasását is feltartja','P2','images',['J5','J6'],['Az első kép kérésének elindítása és ennek megvárása.','Csak ezután a második RecipeImages.mount hívás.','Az első lokális válasz 2000 ms-ot vár, a második azonnali lenne.'],'A második cache-kérés csak 2019.6 ms-nál indul. A korábbi, sorrendet nem garantáló próba önmagában nem volt bizonyító; a rendezett ismétlés igen.',{'firstDelayMs':2000,'secondStartMs':2019.6},'Egyetlen modul-szintű Promise queue fogja össze az összes load feladatot, a független cache-only olvasásokat is.',['recipe-images.js:3','recipe-images.js:49','recipe-images.js:70'],[sup['ref']+'#orderedImageQueue'],'Külön cache-olvasási út és kis párhuzamossági korlát, képenkénti deduplikációval. A generálás kvótája és idempotenciája maradjon védett.',['A második cache-olvasás ≤ 200 ms-on belül elindul a másik generálás mellett.','Ugyanazon képhez nincs dupla generálás.'])
add('PERF-009','A kész képek cache-e leválasztott DOM-elemeket tart meg','P2','memory',['J5','J7'],['Egy kész helyi receptkép bemelegítése.','Ugyanazon kép 100 mount/remove ciklusa.','Kényszerített GC után DOM- és listener-számlálás.'],'682 → 1082 DOM-csomópont és 162 → 262 listener, 100 ismétlés után. Ez célzott komponensszintű életciklusteszt.',S['imageRetention'],'entry.views erős referenciát tart a hostra és paint closure-re. A leválasztott elemeket csak későbbi refresh/paint takarítja; egy kész, nem frissülő képnél ez elmaradhat.',['recipe-images.js:23','recipe-images.js:47','recipe-images.js:48'],[sup['ref']+'#imageRetention'],'Explicit dispose/unmount, observer-lekapcsolás, leválasztott nézetek törlése és korlátos képcache.',['100 mount/unmount után a bemelegített DOM/listener-alapérték közelébe tér vissza.','Látható képek és lejáró signed URL-ek frissítése működik.'])
add('PERF-010','A Gemini handler kliensmegszakítás után is elindíthat providerhívást','P2','reliability',['J6'],['Tényleges voice-command handler injektált fetch-csel.','Request.signal megszakítása 30 ms-nál, auth/quota 120–120 ms.','Providerhívások és válasz ellenőrzése.'],'A megszakítás után is 1 providerhívás indult, a handler kb. 399 ms-nál teljes tesztválaszt adott.',{'abortAtMs':30,'providerCallsAfterAbort':1,'completionMs':399},'A Gemini ág auth/quota/generate hívásai saját határidőjelet kapnak, de nem az ügyfél Request.signal jelét.',['supabase/functions/voice-command/handler.mjs:87','supabase/functions/voice-command/handler.mjs:90','supabase/functions/voice-command/handler.mjs:94','supabase/functions/voice-command/provider.mjs:6'],[pref+'#cases'],'Az ügyfél abortjelének összefűzése minden előkészítő/provider határidővel. Megszakítás után ne induljon új kísérlet vagy fallback.',['Auth közbeni megszakítás után 0 quota- és providerhívás.','Provider-várakozás közbeni megszakítás lezárja az olvasót; nincs fallback.','UI timeout/retry továbbra is helyreáll.'],complexity='S',risk='Injektált handler-teszt. Éles Deno-disconnect és providerelszámolás nem lett mérve.')
add('PERF-011','Átmeneti conversation_page 400 a chat életciklusában','P3','unresolved',['J6'],['A teljes és kiegészítő run conversation_page kéréseinek ellenőrzése.','Új, üres beszélgetés és az első mentett turn körüli időzítés reprodukálása.'],'A teljes futásban három 400-as válasz; a részletes naplózásnál egy Conversation access denied. Három egymás utáni üres chat külön próbája nem reprodukálta.',{'full400Count':3,'supplement400Count':1},'Lehetséges még nem perzisztált thread körüli frissítési verseny; a pontos ok nem bizonyított. A későbbi mentések sikerültek.',['persistence.js:73','persistence.js:88','persistence.js:104'],[full['ref']+'#network',sup['ref']+'#fixtureCalls',sup['ref']+'#emptyChatRequests'],'Korrelált trace az üres → mentett thread átmenetről; a loadThread feltétel csak bizonyított reprodukció után változzon.',['Indokolatlanul tiltott olvasás ne induljon üres threadre.','Valódi jogosultság-visszavonás továbbra is hibaként kezelendő.'],status='hypothesis',complexity='S')
# Keep raw network/console evidence explicit without attributing unrelated errors.
for f in findings:
 if f['id'] == 'PERF-007':
  f['networkRequests']={'kind':'local-sql', 'references':[dbref], 'note':'Direct PGlite execution; no HTTP database round trip was measured.'}
  f['consoleErrors']={'references':[], 'note':'See SQL execution output; not a browser scenario.'}
 elif f['id'] == 'PERF-010':
  f['networkRequests']={'kind':'injected-fetch', 'references':[pref+'#cases'], 'note':'Actual handler modules with injected HTTP responses; no live provider request.'}
  f['consoleErrors']={'references':[pref+'#cases'], 'note':'Handler outcomes are in the case log; not a browser scenario.'}
 else:
  r=sup if f['id'] in ['PERF-008','PERF-009'] else full
  f['networkRequests']={'kind':'local-browser', 'references':[r['ref']+'#network'], 'note':'Whole-run request log. Image lifecycle probes additionally inject local function responses.' if f['id'] in ['PERF-008','PERF-009'] else 'Whole-run request log; not every background request is part of this mechanism.'}
  f['consoleErrors']={'references':[r['ref']+'#errors'], 'note':'Whole-run console log; unrelated and deliberately injected HTTP failures are not evidence of this root cause.'}
def link(ref,label='bizonyíték'):
 parts=ref.split('#',1);return '['+label+'](../../'+parts[0]+')'+(' — '+parts[1] if len(parts)>1 else '')
def details(f):
 return ('### '+f['id']+' — '+f['title']+'\n\n'+f['priority']+' · '+f['validationStatus']+' · bizonyosság: '+f['confidence']+'\n\n'+f['actualBehavior']+'\n\n**Ok:** '+f['rootCause']+'\n\n**Reprodukció:**\n\n'+'\n'.join(str(i+1)+'. '+s for i,s in enumerate(f['reproductionSteps']))+'\n\n**Forrás:** '+', '.join('['+ref+']('+str(Path(meta['snapshotRoot'])/ref)+')' for ref in f['sourceFiles'])+'\n\n**Bizonyíték:** '+' · '.join(link(e) for e in f['evidence'])+'\n\n**Javaslat:** '+f['recommendedRemediation']+'\n\n**Elfogadás:**\n\n'+'\n'.join('- '+s for s in f['acceptanceCriteria'])+'\n\n')
def subset(*ids):return ''.join(details(f) for f in findings if f['id'] in ids)
def header(t):return '# '+t+'\n\n2026. november 16. · rögzített alkalmazáspillanatkép · szintetikus helyi adatok.\n\n'
