js=json.dumps({'schemaVersion':1,'generatedAt':generated_at,'revision':meta['revision'],'snapshotCapturedAt':meta['capturedAt'],'snapshotRoot':meta['snapshotRoot'],'inputs':inputs,'findings':findings},ensure_ascii=False,indent=2)
(out/'findings.json').write_text(js)
